CREATE COLUMN TABLE "TEST_AP"."AAC1" ("Code" NVARCHAR(20) NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "DprAreaID" NVARCHAR(15) NOT NULL , "Active" NVARCHAR(1) DEFAULT 'Y', "AcctDtn" NVARCHAR(15), "DprTypID" NVARCHAR(15), "UseLife" INTEGER CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "SnapshotId" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("Code", "LineNum", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "AAC1_UNIQUE" ON "TEST_AP"."AAC1" ( "Code" ASC, "DprAreaID" ASC, "LogInstanc" ASC )